      CommsLine(id: 'weaponPickup.spread.h3', speaker: 'sunny', duration: 2.599, text: 'Spread shot! Spreading joy, one demon at a time.', mouth: '003443344222445454455454454433333322000', signature: true),
    ],
  ),
