      CommsLine(id: 'weaponPickup.powerful.h1', speaker: 'sparrow', duration: 2.179, text: 'Heavy shots fitted. Hit them hard.', mouth: '444544443335352000035454443220000'),
      CommsLine(id: 'weaponPickup.powerful.h2', speaker: 'wisp', duration: 2.446, text: 'Heavy rounds. Fewer shots, bigger holes.', mouth: '2244444444552244444432534344455532000'),
