      CommsLine(id: 'weaponPickup.large.h1', speaker: 'wisp', duration: 2.15, text: 'Area rounds. They\'ll splash the pack.', mouth: '444544444455345335443353332220000'),
      CommsLine(id: 'weaponPickup.large.h2', speaker: 'sparrow', duration: 2.038, text: 'Blast rounds loaded. Boom!', mouth: '4544333445353322200000454322000'),
