    priority: 4,
    cooldown: 14.0,
    ttl: 2.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'homingPickup.h0', speaker: 'admiral', duration: 1.492, text: 'Homing missiles armed!', mouth: '22445454435334433220000'),
      CommsLine(id: 'homingPickup.h1', speaker: 'wisp', duration: 1.778, text: 'Missiles locked and seeking.', mouth: '444444334442235533353520000'),
      CommsLine(id: 'homingPickup.h2', speaker: 'rook', duration: 2.007, text: 'Homing missiles! They really get attached.', mouth: '4454544455333454444334432200000', signature: true),
      CommsLine(id: 'homingPickup.h3', speaker: 'anvil', duration: 2.661, text: 'Seekers loaded. Let them do the aiming.', mouth: '2233223335453320000053533335333333220000'),
      CommsLine(id: 'homingPickup.h4', speaker: 'march', duration: 2.96, text: 'Bastion sees your missiles. Send some our way!', mouth: '444433453355334543322220002345333335544320000'),
    ],
  ),
  'lifeLost': CommsTriggerSpec(
    name: 'lifeLost',
    priority: 6,
    cooldown: 8.0,
    ttl: 2.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'lifeLost.h0', speaker: 'admiral', duration: 3.11, text: 'Ship\'s totalled, pilot\'s safe. Next ship, launch!', mouth: '22333234445534445344320000005443333554435320000'),
      CommsLine(id: 'lifeLost.h1', speaker: 'sparrow', duration: 1.793, text: 'Shake it off. You\'re still in this.', mouth: '224544433000044445453222000'),
      CommsLine(id: 'lifeLost.h2', speaker: 'anvil', duration: 1.97, text: 'Took a hit. Breathe. Back in.', mouth: '335333552223453322444333200000'),
      CommsLine(id: 'lifeLost.h3', speaker: 'rook', duration: 1.58, text: 'Ouch! Get them back for that one.', mouth: '335335455443344333200000'),
      CommsLine(id: 'lifeLost.h4', speaker: 'nomad', duration: 3.59, text: 'Pod\'s away and safe. Spare ship\'s warm. Go.', mouth: '444445544444533444220000234444444335555553004443332000'),
      CommsLine(id: 'lifeLost.h5', speaker: 'lindqvist', duration: 3.403, text: 'Ejected clean. Recovery has you. Launch the reserve.', mouth: '4345332223543533333333333322000035553333553332000000'),
    ],
  ),
  'lowLives': CommsTriggerSpec(
    name: 'lowLives',
    priority: 7,
    cooldown: 40.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'lowLives.h0', speaker: 'admiral', duration: 3.014, text: 'Last ship, pilot. The whole fleet is behind you.', mouth: '4544444322333330000034555445335433344533220000'),
      CommsLine(id: 'lowLives.h1', speaker: 'sparrow', duration: 2.704, text: 'Last one. I believe in you. Let\'s finish this.', mouth: '44443533200034455545533224433443322222000'),
      CommsLine(id: 'lowLives.h2', speaker: 'anvil', duration: 2.996, text: 'One ship left. Slow down, pick your shots.', mouth: '355444453544200000033555444433333334432222000'),
      CommsLine(id: 'lowLives.h3', speaker: 'wisp', duration: 2.952, text: 'Final reserve ship. Stay calm. You can do this.', mouth: '004444544444445300003443344435333545553220000'),
      CommsLine(id: 'lowLives.h4', speaker: 'nomad', duration: 3.407, text: 'One ship, one pilot. That\'s always been enough.', mouth: '4544444442005445444443200003333555444544454332200000'),
    ],
  ),
  'extraLife': CommsTriggerSpec(
    name: 'extraLife',
    priority: 4,
    cooldown: 20.0,
    ttl: 2.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'extraLife.h0', speaker: 'admiral', duration: 2.718, text: 'Heart assembled. Reserve ship on the line.', mouth: '22444544543320000045444333354545443222000'),
      CommsLine(id: 'extraLife.h1', speaker: 'rook', duration: 1.52, text: 'Extra ship! You lucky thing.', mouth: '22223444555433333322000'),
      CommsLine(id: 'extraLife.h2', speaker: 'sparrow', duration: 1.967, text: 'Spare ship ready. Nice work.', mouth: '323543333333220005453353200000'),
      CommsLine(id: 'extraLife.h3', speaker: 'sunny', duration: 2.012, text: 'A whole new ship! You\'ve got a big heart.', mouth: '3335455444433354445333333200000', signature: true),
    ],
  ),
  'salvage': CommsTriggerSpec(
    name: 'salvage',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'salvage.h0', speaker: 'anvil', duration: 2.44, text: 'Wave\'s clear. Sweep up the salvage.', mouth: '3554444334432223355543334445332222000'),
      CommsLine(id: 'salvage.h1', speaker: 'rook', duration: 1.529, text: 'Loot time! Grab everything.', mouth: '45544445444543333320000'),
      CommsLine(id: 'salvage.h2', speaker: 'wisp', duration: 2.376, text: 'Salvage drifting. Collect what you can.', mouth: '334444433443335522454333335344552000'),
      CommsLine(id: 'salvage.h3', speaker: 'kestrel', duration: 2.779, text: 'Salvage on the field. Quick pass, then regroup.', mouth: '224445444433554322222234433345543335200000'),
    ],
  ),
  'levelClear': CommsTriggerSpec(
    name: 'levelClear',
    priority: 5,
    cooldown: 10.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'levelClear.h0', speaker: 'admiral', duration: 2.572, text: 'Sector secure. Outstanding flying.', mouth: '223333343535333000045444455335443220000'),
      CommsLine(id: 'levelClear.h1', speaker: 'sparrow', duration: 1.695, text: 'We did it! Sky\'s ours.', mouth: '45544420002344453332220000'),
      CommsLine(id: 'levelClear.h2', speaker: 'rook', duration: 1.764, text: 'Ha! Did you see that? Textbook.', mouth: '334554445544223333333200000'),
      CommsLine(id: 'levelClear.h3', speaker: 'wisp', duration: 2.091, text: 'Scopes clear. Good work, everyone.', mouth: '33344333444555544433343544530000'),
      CommsLine(id: 'levelClear.h4', speaker: 'nomad', duration: 2.698, text: 'Clean sweep. Proud to fly with you.', mouth: '33445533444500000444554444444544443520000'),
      CommsLine(id: 'levelClear.h5', speaker: 'pip', duration: 2.08, text: 'That was amazing! Can we do it again?', mouth: '44454544443335345454543333220000'),
    ],
  ),
  'flawlessSector': CommsTriggerSpec(
    name: 'flawlessSector',
    priority: 6,
    cooldown: 10.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'flawlessSector.h0', speaker: 'admiral', duration: 3.696, text: 'Not a single ship lost in this sector. Textbook, all of you.', mouth: '45445445544453354433553333333300000233333333445433352000'),
      CommsLine(id: 'flawlessSector.h1', speaker: 'kestrel', duration: 2.595, text: 'Every wing accounted for. That\'s how it\'s done.', mouth: '454455545334433225332244333443333220000'),
      CommsLine(id: 'flawlessSector.h2', speaker: 'sunny', duration: 2.183, text: 'Zero losses! That was out of this world.', mouth: '334445444435333554445333533320000', signature: true),
      CommsLine(id: 'flawlessSector.h3', speaker: 'march', duration: 4.111, text: 'Bastion reporting. Every ground team is still standing. Thank you!', mouth: '44443345433554435223344444445335553333333335322000033522220000'),
    ],
  ),
  'flawlessVictory': CommsTriggerSpec(
    name: 'flawlessVictory',
    priority: 9,
    cooldown: 30.0,
    ttl: 6.0,
    mood: CommsMood.happy,
    chain: 2,
    lines: [
      CommsLine(id: 'flawlessVictory.h0', speaker: 'admiral', duration: 5.455, text: 'All hands, all ships, all squads. Every one of you is coming home. Fleet intact!', mouth: '4445444445444443333334533543333200000044445444555333353445550000002444533332222000'),
      CommsLine(id: 'flawlessVictory.h1', speaker: 'lindqvist', duration: 4.11, text: 'Beacon confirms. Full roster, no losses. I\'ve never seen it done.', mouth: '44444533544435330000003555433335445433333333543333443533352000'),
      CommsLine(id: 'flawlessVictory.h2', speaker: 'rook', duration: 2.203, text: 'Perfect run! I\'m over the moon! All the moons!', mouth: '3232444433553354333355333322220000', signature: true),
      CommsLine(id: 'flawlessVictory.h3', speaker: 'sunny', duration: 2.585, text: 'Flawless! Somebody get this pilot a constellation!', mouth: '355444533444433333344322353353522222000', signature: true),
      CommsLine(id: 'flawlessVictory.h4', speaker: 'pip', duration: 2.51, text: 'Everybody made it? Everybody? Best day ever!', mouth: '44444545544422454544554444444433320000'),
      CommsLine(id: 'flawlessVictory.h5', speaker: 'kessler', duration: 2.724, text: 'Ground\'s all present! Drinks are on Bulwark tonight!', mouth: '35444445534443200244444445455543333320000'),
    ],
  ),
  'flawlessRun': CommsTriggerSpec(
    name: 'flawlessRun',
    priority: 10,
    cooldown: 60.0,
    ttl: 8.0,
    mood: CommsMood.happy,
    chain: 3,
    lines: [
      CommsLine(id: 'flawlessRun.h0', speaker: 'admiral', duration: 5.216, text: 'Five tours. Not one ship, not one squad lost. The whole fleet salutes you, pilot.', mouth: '0044443354330054454444433443545334435333322200000034552244334555333533333220000'),
      CommsLine(id: 'flawlessRun.h1', speaker: 'nomad', duration: 4.939, text: 'Thirty years flying, and this is the run I\'ll tell stories about.', mouth: '004444444444432244443530000045443320004444554455335534533345544435333220000'),
      CommsLine(id: 'flawlessRun.h2', speaker: 'kestrel', duration: 4.169, text: 'Every wing, every crew, every squad. Fleet intact. Legendary.', mouth: '444455444544443224443334443354432225545543322000054445333220000'),
      CommsLine(id: 'flawlessRun.h3', speaker: 'sparrow', duration: 2.783, text: 'Not a scratch on the whole fleet! You\'re unbelievable!', mouth: '444433344335335522222200003445455433222000'),
      CommsLine(id: 'flawlessRun.h4', speaker: 'mensah', duration: 3.524, text: 'Granite to air wing. Every trooper down here is cheering for you.', mouth: '33444443444533352233432225333443353322233352255522000'),
      CommsLine(id: 'flawlessRun.h5', speaker: 'voss', duration: 3.635, text: 'Lantern here. All lights on, all teams home. Thank you, pilot!', mouth: '4445434544300044545344334533353445520000444353444322000'),
    ],
  ),
  'bossArrival': CommsTriggerSpec(
    name: 'bossArrival',
    priority: 9,
    cooldown: 30.0,
    ttl: 4.0,
    lines: [
      CommsLine(id: 'bossArrival.h0', speaker: 'admiral', duration: 3.409, text: 'Carrier contact! Break its shield, then hit the hatch!', mouth: '2244444334433332000000454543355452245435343322330000'),
      CommsLine(id: 'bossArrival.h1', speaker: 'anvil', duration: 3.401, text: 'Here comes the big one. Shield first, then the core.', mouth: '0044334433354455320000023445322444322333333555200000'),
      CommsLine(id: 'bossArrival.h2', speaker: 'rook', duration: 2.288, text: 'Oh, that\'s huge. That is really, really huge.', mouth: '33344334553224453354453332222200000'),
      CommsLine(id: 'bossArrival.h3', speaker: 'wisp', duration: 3.246, text: 'Carrier field is up. Wear it down before the hatch opens.', mouth: '2244443344354430000004444444335444333555355532000'),
      CommsLine(id: 'bossArrival.h4', speaker: 'lindqvist', duration: 3.478, text: 'Carrier in range. All fleet guns, support the pilot.', mouth: '22444444544445330000255333333444554433533533332220000'),
    ],
  ),
  'bossPhase': CommsTriggerSpec(
    name: 'bossPhase',
    priority: 6,
    cooldown: 10.0,
    ttl: 2.0,
    lines: [
      CommsLine(id: 'bossPhase.h0', speaker: 'admiral', duration: 2.495, text: 'It\'s changing form. Stay on the hatch.', mouth: '44533455453353352000334444444432220000'),
      CommsLine(id: 'bossPhase.h1', speaker: 'wisp', duration: 2.105, text: 'Carrier\'s adapting. New pattern.', mouth: '22444444444335453544533333550000'),
      CommsLine(id: 'bossPhase.h2', speaker: 'anvil', duration: 1.905, text: 'Field\'s down! Hit the core!', mouth: '22344533444433353233455220000'),
      CommsLine(id: 'bossPhase.h3', speaker: 'sparrow', duration: 2.514, text: 'It\'s getting angry. Good. Keep going.', mouth: '43334554453322000024452002222443222000'),
      CommsLine(id: 'bossPhase.h4', speaker: 'kestrel', duration: 2.525, text: 'New form. Same weak spot. Find the hatch.', mouth: '45444454533455432333300044543332222000'),
    ],
  ),
  'bossDefeated': CommsTriggerSpec(
    name: 'bossDefeated',
    priority: 7,
    cooldown: 20.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'bossDefeated.h0', speaker: 'admiral', duration: 3.145, text: 'The Carrier is down! All ships, the fleet salutes you.', mouth: '424444444533333520000454444333225333555333220000'),
      CommsLine(id: 'bossDefeated.h1', speaker: 'rook', duration: 1.693, text: 'It\'s falling! It\'s actually falling!', mouth: '22345455444335334433220000'),
      CommsLine(id: 'bossDefeated.h2', speaker: 'anvil', duration: 2.808, text: 'Target destroyed. Hell of a run, pilot.', mouth: '3344333333355320000004454555444322443220000'),
      CommsLine(id: 'bossDefeated.h3', speaker: 'sparrow', duration: 1.555, text: 'Carrier down! Woohoo!', mouth: '224444533322005533320000'),
      CommsLine(id: 'bossDefeated.h4', speaker: 'sunny', duration: 2.251, text: 'Carrier down! Looks like it\'s lights out for them.', mouth: '2244444444555544443345433333352000', signature: true),
    ],
  ),
  'defeat': CommsTriggerSpec(
    name: 'defeat',
    priority: 10,
    cooldown: 30.0,
    ttl: 4.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'defeat.h0', speaker: 'admiral', duration: 5.002, text: 'All ships totalled, but every pilot is safe. Regroup at base. We go again.', mouth: '4444335333354453344445334433533332220000054454454533333320000054445333520000'),
      CommsLine(id: 'defeat.h1', speaker: 'admiral', duration: 3.805, text: 'That\'s the last reserve. Bring it home, pilot. We\'ll launch again.', mouth: '4444345444335333220000004444445433353320055544543333520000'),
      CommsLine(id: 'defeat.h2', speaker: 'lindqvist', duration: 4.061, text: 'Recovery has your pod. Rest up. The fleet will be ready when you are.', mouth: '4454444443334552244333433332000000333445354544455454544332000'),
    ],
  ),
  'groundForceSighted': CommsTriggerSpec(
    name: 'groundForceSighted',
    priority: 5,
    cooldown: 18.0,
    ttl: 3.0,
    lines: [
      CommsLine(id: 'groundForceSighted.h0', speaker: 'admiral', duration: 1.511, text: 'Ground forces ahead!', mouth: '22444535333543433220000'),
      CommsLine(id: 'groundForceSighted.h1', speaker: 'wisp', duration: 2.619, text: 'Demon ground troops below. Marking them now.', mouth: '4445444444533333344445224433555543320000'),
      CommsLine(id: 'groundForceSighted.h2', speaker: 'anvil', duration: 2.728, text: 'Movement on the ground. Brood infantry.', mouth: '33553344433344432220002455544533333320000'),
      CommsLine(id: 'groundForceSighted.h3', speaker: 'kessler', duration: 2.727, text: 'Bulwark here. Brood walkers moving on our line!', mouth: '44554422442002453544333355433333333220000'),
      CommsLine(id: 'groundForceSighted.h4', speaker: 'march', duration: 4.295, text: 'Bastion to air wing. Enemy armor on the ground, your side of the ridge.', mouth: '44443345333444554452000024555334454455344333223333333333322220000'),
      CommsLine(id: 'groundForceSighted.h5', speaker: 'mensah', duration: 3.131, text: 'Granite here. They\'re massing below you. Lots of them.', mouth: '33444444444444443335355455335200544222222220000'),
    ],
  ),
  'groundForceInRange': CommsTriggerSpec(
    name: 'groundForceInRange',
    priority: 6,
    cooldown: 14.0,
    ttl: 2.0,
    lines: [
      CommsLine(id: 'groundForceInRange.h0', speaker: 'sparrow', duration: 2.132, text: 'Ground targets in range. Fire!', mouth: '45445333333553335330000244322000'),
      CommsLine(id: 'groundForceInRange.h1', speaker: 'rook', duration: 1.52, text: 'Strafing run! Hit them now!', mouth: '22444454453353543322000'),
      CommsLine(id: 'groundForceInRange.h2', speaker: 'anvil', duration: 2.296, text: 'They\'re under your guns. Take the shot.', mouth: '22445444555544322200233333444320000'),
      CommsLine(id: 'groundForceInRange.h3', speaker: 'voss', duration: 2.497, text: 'Lantern here. They\'re right under you. Light them up!', mouth: '44454444443005444443545522445344200000'),
      CommsLine(id: 'groundForceInRange.h4', speaker: 'mensah', duration: 2.209, text: 'You\'re right over them. Bring the rain!', mouth: '3335444453233320033553533322200000'),
    ],
  ),
  'allyUnderAttack': CommsTriggerSpec(
    name: 'allyUnderAttack',
    priority: 7,
    cooldown: 14.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'allyUnderAttack.h0', speaker: 'kessler', duration: 1.88, text: 'We\'re pinned down. Need air support!', mouth: '45334454444554444433225300000'),
      CommsLine(id: 'allyUnderAttack.h1', speaker: 'kessler', duration: 2.356, text: 'Please shoot these enemies! They\'re all over us!', mouth: '225433335353344432223444554332220000'),
      CommsLine(id: 'allyUnderAttack.h2', speaker: 'voss', duration: 2.946, text: 'Pick up some homing missiles! We need them off our backs!', mouth: '334443353345453335530005454544433344433330000'),
      CommsLine(id: 'allyUnderAttack.h3', speaker: 'march', duration: 4.324, text: 'Bastion to air wing, my teams are taking fire. Requesting support!', mouth: '44443345333445444553333555333335334433220000223443355333353222000'),
      CommsLine(id: 'allyUnderAttack.h4', speaker: 'mensah', duration: 3.557, text: 'Granite\'s surrounded! Anything you\'ve got, send it down!', mouth: '334444334544445223444555334432223552233332200000000000'),
      CommsLine(id: 'allyUnderAttack.h5', speaker: 'voss', duration: 2.436, text: 'Lantern to air wing, we\'re taking fire! Help!', mouth: '4544453534454353333453344430033300000'),
    ],
  ),
  'allySaved': CommsTriggerSpec(
    name: 'allySaved',
    priority: 5,
    cooldown: 12.0,
    ttl: 3.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'allySaved.h0', speaker: 'kessler', duration: 2.114, text: 'That did it! Thanks for the cover, flyer!', mouth: '44433555004433454444335443220000'),
      CommsLine(id: 'allySaved.h1', speaker: 'voss', duration: 1.894, text: 'They\'re scattering! We owe you one!', mouth: '44444444435200544445554320000'),
